  private static BigDecimal fee(Fee fr, BigDecimal amtCcy) {
    if (fr==null) return bd("0").setScale(2,RM);
    int s = amtCcy.signum(); boolean debit=s<0, credit=s>0;
    boolean applies = "ALL".equals(fr.applies) || ("DEBIT".equals(fr.applies)&&debit) || ("CREDIT".equals(fr.applies)&&credit);
    if (!applies) return bd("0").setScale(2,RM);
    BigDecimal base = fr.flat.add(fr.pct.multiply(amtCcy.abs()));
    BigDecimal f = base.setScale(2,RM);
    if (f.compareTo(fr.min)<0) f=fr.min;
    if (f.compareTo(fr.max)>0) f=fr.max;
    return f.setScale(2,RM);
  }

  private static Fx latest(List<Fx> all, String from, String to, Date eff) {
    Fx best=null;
    for (Fx r: all) {
      if (!r.f.equals(from) || !r.t.equals(to)) continue;
      if (r.d.after(eff)) continue;
      if (best==null || r.d.after(best.d)) best=r;
    }
    return best;
  }

  private static BigDecimal leg(List<Fx> all, String from, String to, Date eff) {
    Fx d = latest(all, from, to, eff);
    Fx rev = latest(all, to, from, eff);
    if (d==null && rev==null) return null;
    if (d!=null && rev==null) return d.r.setScale(10,RM);
    if (d==null && rev!=null) return bd("1").divide(rev.r,10,RM);
    int cmp = d.d.compareTo(rev.d);
    if (cmp>0) return d.r.setScale(10,RM);
    if (cmp<0) return bd("1").divide(rev.r,10,RM);
    return d.r.setScale(10,RM);
  }

  private static BigDecimal fxRate(List<Fx> all, List<String> pivots, String from, String to, Date eff) {
    BigDecimal x = leg(all,from,to,eff);
    if (x!=null) return x;
    for (String p: pivots) {
      if (p.equals(from) || p.equals(to)) continue;
      BigDecimal a = leg(all,from,p,eff); if (a==null) continue;
      BigDecimal b = leg(all,p,to,eff); if (b==null) continue;
      return a.multiply(b).setScale(10,RM);
    }
    return null;
  }

