    BigDecimal eod, apr, diRaw;
  }
  static class Fee { String plan, applies; BigDecimal flat,pct,min,max; }
  static class Txn {
    int row; String txId, acctId; Date eff; BigDecimal amt; String ccy,status,revOf;
    boolean valid; String reason;
    BigDecimal convRaw, fee, adj;
  }
  static class Fx { Date d; String f,t; BigDecimal r; }

  public static void main(String[] args) throws Exception {
    OUT_DIR.mkdirs();
    del("interest.csv"); del("exceptions.csv"); del("stats.json");
    del("bankdb.h2.db"); del("bankdb.trace.db"); del("bankdb.lock.db");

    Date biz = parse(readAll(new File(DATA_DIR,"biz_date.txt")).trim());
    Map<String,Acct> accts = readAccounts(new File(DATA_DIR,"accounts.csv"));
    Map<String,Fee> fees = readFees(new File(DATA_DIR,"fee_rules.csv"));
    List<String> pivots = readPivots(new File(DATA_DIR,"fx_pivots.csv"));
    List<Fx> fx = readFx(new File(DATA_DIR,"fx_rates.csv"));
    List<Txn> txns = readTxns(new File(DATA_DIR,"transactions.csv"));

    Set<String> txIds = new HashSet<String>();
    for (Txn t: txns) txIds.add(t.txId);

    Set<String> reversed = new HashSet<String>();
    for (Txn t: txns) {
      if (t.revOf.length()>0 && txIds.contains(t.revOf)) { reversed.add(t.txId); reversed.add(t.revOf); }
    }

    Set<String> seen = new HashSet<String>();
    int valid=0, skipped=0;

    for (Txn t: txns) {
      boolean dup = seen.contains(t.txId); seen.add(t.txId);
      String reason=null;

      if (reversed.contains(t.txId)) reason="REVERSED";
      else if (t.revOf.length()>0 && !txIds.contains(t.revOf)) reason="REVERSAL_MISSING";
      else {
        Acct a = accts.get(t.acctId);
        if (a==null) reason="ACCOUNT_MISSING";
        else {
          BigDecimal rate;
          if (t.ccy.equals(a.ccy)) rate = BigDecimal.ONE.setScale(10,RM);
          else {
            rate = fxRate(fx,pivots,t.ccy,a.ccy,t.eff);
            if (rate==null) reason="FX_MISSING";
          }
          if (reason==null) {
            if (t.eff.after(biz)) reason="AFTER_BIZ_DATE";
            else if (!"POSTED".equals(t.status)) reason=t.status;
            else if (dup) reason="DUPLICATE";
            else {
              // convert first, keep 10dp, then fee uses converted amount
              t.convRaw = t.amt.multiply(rate).setScale(10,RM);
              Fee fr = fees.get(a.feePlan);
              t.fee = fee(fr, t.convRaw);
              t.adj = t.convRaw.setScale(2,RM).subtract(t.fee).setScale(2,RM);
              t.valid=true; valid++;
            }
          }
        }
      }

      if (reason!=null) { t.valid=false; t.reason=reason; skipped++; }
    }

    for (Acct a: accts.values()) {
      BigDecimal sum = bd("0").setScale(2,RM);
      for (Txn t: txns) if (t.valid && a.id.equals(t.acctId)) sum = sum.add(t.adj).setScale(2,RM);
      a.eod = a.start.add(sum).setScale(2,RM);

      boolean promo=false;
      if (a.promoDays>0) promo = daysBetween(a.opened,biz) < a.promoDays;

      BigDecimal apr=a.baseApr;
      if (a.eod.compareTo(a.tierTh)>=0) apr=apr.add(a.tierApr);
      if (promo) apr=apr.add(a.promoApr);
      a.apr=apr;

      BigDecimal principal = a.eod.max(bd("0").setScale(2,RM));
      BigDecimal dailyRate = a.apr.divide(bd("365"),10,RM);
      a.diRaw = principal.multiply(dailyRate).setScale(10,RM);
    }

    File interest = new File(OUT_DIR,"interest.csv");
    writeInterest(interest,biz,accts);
    String md5 = md5hex(interest);

    writeExceptions(new File(OUT_DIR,"exceptions.csv"), txns);

    BigDecimal totalRaw = bd("0").setScale(10,RM);
    for (Acct a: accts.values()) totalRaw = totalRaw.add(a.diRaw).setScale(10,RM);
    BigDecimal total = totalRaw.setScale(2,RM);

    writeStats(new File(OUT_DIR,"stats.json"), biz, accts.size(), valid, skipped, total, md5);
    writeDb(biz, accts, txns, valid, skipped, md5);
  }

  private static void del(String name){ File f=new File(OUT_DIR,name); if(f.exists()) f.delete(); }
  private static BigDecimal bd(String s){ return new BigDecimal(s); }
  private static Date parse(String s) throws Exception { synchronized(DF){ return DF.parse(s);} }
  private static String fmt(Date d){ synchronized(DF){ return DF.format(d);} }
  private static int daysBetween(Date s, Date e){ return (int)((e.getTime()-s.getTime())/86400000L); }

  private static String readAll(File f) throws Exception {
    BufferedReader br=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"));
    try{ StringBuilder sb=new StringBuilder(); String line; while((line=br.readLine())!=null) sb.append(line); return sb.toString(); }
    finally{ br.close(); }
  }

  private static List<String[]> csv(File f) throws Exception {
    BufferedReader br=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"));
    try{
      List<String[]> rows=new ArrayList<String[]>();
      String line; while((line=br.readLine())!=null){
        String[] p=line.split(",",-1);
        for(int i=0;i<p.length;i++) p[i]=p[i].trim();
        rows.add(p);
      }
      return rows;
    } finally { br.close(); }
  }

  private static Map<String,Acct> readAccounts(File f) throws Exception {
    List<String[]> r=csv(f); Map<String,Acct> m=new HashMap<String,Acct>();
    for(int i=1;i<r.size();i++){
      String[] x=r.get(i);
      Acct a=new Acct();
      a.id=x[0]; a.opened=parse(x[1]); a.start=bd(x[2]).setScale(2,RM);
      a.baseApr=bd(x[3]); a.promoApr=bd(x[4]); a.promoDays=Integer.parseInt(x[5]);
      a.tierTh=bd(x[6]).setScale(2,RM); a.tierApr=bd(x[7]); a.ccy=x[8]; a.feePlan=x[9];
      m.put(a.id,a);
    }
    return m;
  }

  private static Map<String,Fee> readFees(File f) throws Exception {
    List<String[]> r=csv(f); Map<String,Fee> m=new HashMap<String,Fee>();
    for(int i=1;i<r.size();i++){
      String[] x=r.get(i);
      Fee fr=new Fee(); fr.plan=x[0]; fr.applies=x[1];
      fr.flat=bd(x[2]); fr.pct=bd(x[3]); fr.min=bd(x[4]); fr.max=bd(x[5]);
      m.put(fr.plan,fr);
    }
    return m;
  }

  private static List<String> readPivots(File f) throws Exception {
    List<String[]> r=csv(f); List<String> p=new ArrayList<String>();
    for(int i=1;i<r.size();i++) p.add(r.get(i)[0]);
    return p;
  }

  private static List<Fx> readFx(File f) throws Exception {
    List<String[]> r=csv(f); List<Fx> list=new ArrayList<Fx>();
    for(int i=1;i<r.size();i++){
      String[] x=r.get(i);
      Fx k=new Fx(); k.d=parse(x[0]); k.f=x[1]; k.t=x[2]; k.r=bd(x[3]);
      list.add(k);
    }
    return list;
  }

  private static List<Txn> readTxns(File f) throws Exception {
    List<String[]> r=csv(f); List<Txn> list=new ArrayList<Txn>();
    for(int i=1;i<r.size();i++){
      String[] x=r.get(i);
      Txn t=new Txn();
      t.row=i; t.txId=x[0]; t.acctId=x[1]; t.eff=parse(x[2]); t.amt=bd(x[3]).setScale(2,RM);
      t.ccy=x[4]; t.status=x[5]; t.revOf=(x.length>6?x[6]:""); if(t.revOf==null) t.revOf="";
      list.add(t);
    }
    return list;
  }
